using System;using System.IO;using System.Collections.Generic;using System.Drawing.Printing;using System.Windows.Forms;
namespace EanEtikety {
public class PrinterProfile {
 public string Printer,Paper,Name;public int Width,Height;public bool Landscape,IgnoreDriverMargins;public double X,Y,ScaleX=1,ScaleY=1;
 public string DisplayName {get{return string.IsNullOrWhiteSpace(Name)?(Paper??"")+" ("+(Width*.254).ToString("0.##")+" × "+(Height*.254).ToString("0.##")+" mm)":Name;}}
 public PrinterProfile Copy(){return (PrinterProfile)MemberwiseClone();}
 public override string ToString(){return DisplayName;}
}
public class PrinterProfileStore {
 readonly string path;public List<PrinterProfile> Profiles=new List<PrinterProfile>();
 public PrinterProfileStore(string file){path=file;if(File.Exists(path))Profiles=ProjectXml.Decode<List<PrinterProfile>>(File.ReadAllText(path));}
 public List<PrinterProfile> ForPrinter(string name){return Profiles.FindAll(p=>string.Equals(p.Printer,name,StringComparison.OrdinalIgnoreCase));}
 public PrinterProfile Find(string name){return Profiles.FindLast(p=>string.Equals(p.Printer,name,StringComparison.OrdinalIgnoreCase));}
 public PrinterProfile Find(string printer,string name){return Profiles.Find(p=>string.Equals(p.Printer,printer,StringComparison.OrdinalIgnoreCase)&&string.Equals(p.DisplayName,name,StringComparison.OrdinalIgnoreCase));}
 public void Save(PrinterProfile value){if(value==null||string.IsNullOrWhiteSpace(value.Printer)||value.Width<1||value.Height<1||value.Width>20000||value.Height>20000||double.IsNaN(value.X)||double.IsNaN(value.Y)||double.IsInfinity(value.X)||double.IsInfinity(value.Y)||Math.Abs(value.X)>100||Math.Abs(value.Y)>100)throw new ArgumentException(Loc.T("Neplatný profil média."));new PrintCalibration{X=value.X,Y=value.Y,ScaleX=value.ScaleX,ScaleY=value.ScaleY}.Validate();var copy=value.Copy();copy.Name=copy.DisplayName.Trim();if(copy.Name.Length>120)throw new ArgumentException(Loc.T("Neplatný profil média."));var next=new List<PrinterProfile>(Profiles);next.RemoveAll(p=>string.Equals(p.Printer,copy.Printer,StringComparison.OrdinalIgnoreCase)&&string.Equals(p.DisplayName,copy.Name,StringComparison.OrdinalIgnoreCase));next.Add(copy);ProjectXml.Save(path,next);Profiles=next;}
 public void Delete(string printer,string name){var next=new List<PrinterProfile>(Profiles);next.RemoveAll(p=>string.Equals(p.Printer,printer,StringComparison.OrdinalIgnoreCase)&&string.Equals(p.DisplayName,name,StringComparison.OrdinalIgnoreCase));ProjectXml.Save(path,next);Profiles=next;}
}
public partial class PrintPanel {
 PrinterProfileStore profiles;PrinterProfile requestedProfile;readonly ModernComboBox mediaProfiles=new ModernComboBox();readonly TextBox profileName=new TextBox();readonly CheckBox ignoreDriverMargins=new CheckBox();readonly NumericUpDown offsetX=new NumericUpDown(),offsetY=new NumericUpDown(),scaleX=new NumericUpDown(),scaleY=new NumericUpDown();ModernButton calibrationLaunch;
 public void LoadProfiles(string path){try{profiles=new PrinterProfileStore(path);}catch(Exception ex){info.Text=Loc.T("Profil tlačiarne sa nepodarilo načítať")+": "+ex.Message;}}
 void ProfileSelector(TableLayoutPanel fields){Add(fields,new Label{Text=Loc.T("Profil média"),AutoSize=true});mediaProfiles.DropDownStyle=ComboBoxStyle.DropDownList;mediaProfiles.AccessibleName=Loc.T("Profil média");Add(fields,mediaProfiles);mediaProfiles.SelectedIndexChanged+=delegate{if(updating||sending)return;var profile=mediaProfiles.SelectedItem as PrinterProfile;if(profile==null)return;requestedProfile=profile.Copy();selectedPage=null;selectedPrinter=null;StartRequest(false,false);};}
 void RefreshProfiles(string printer,string name){mediaProfiles.Items.Clear();if(profiles!=null)foreach(var profile in profiles.ForPrinter(printer)){mediaProfiles.Items.Add(profile);if(string.Equals(profile.DisplayName,name,StringComparison.OrdinalIgnoreCase))mediaProfiles.SelectedItem=profile;}}
 void SaveMediaProfile(){if(calibrationTargetMode)return;try{if(profiles==null||selectedPrinter==null||selectedPage==null||busy||sending)throw new InvalidOperationException(Loc.T("Vybraná tlačiareň nie je dostupná."));var profile=new PrinterProfile{Printer=selectedPrinter.PrinterName,Name=profileName.Text.Trim(),Paper=selectedPage.PaperSize.PaperName,Width=selectedPage.PaperSize.Width,Height=selectedPage.PaperSize.Height,Landscape=selectedPage.Landscape,X=(double)offsetX.Value,Y=(double)offsetY.Value,ScaleX=(double)scaleX.Value/100,ScaleY=(double)scaleY.Value/100,IgnoreDriverMargins=ignoreDriverMargins.Checked};profiles.Save(profile);updating=true;try{RefreshProfiles(profile.Printer,profile.DisplayName);profileName.Text=profile.DisplayName;}finally{updating=false;}info.Text=Loc.T("Profil tlačiarne uložený");}catch(Exception ex){info.Text=ex.Message;}}
 void UseDocumentPaper(){if(selectedPage==null||busy||sending||calibrationTargetMode)return;double width=outputPlan==null?(snapshot.UsePaper||snapshot.Sheet?snapshot.PageWidth:snapshot.Width):outputPlan.Width,height=outputPlan==null?(snapshot.UsePaper||snapshot.Sheet?snapshot.PageHeight:snapshot.Height):outputPlan.Height;var size=new PaperSize(Loc.T("Rozmery dokumentu"),(int)Math.Round((selectedPage.Landscape?height:width)/.254),(int)Math.Round((selectedPage.Landscape?width:height)/.254));updating=true;try{papers.Items.Add(size);papers.SelectedItem=size;selectedPage.PaperSize=size;}finally{updating=false;}Schedule();}
 void ProfileControls(TableLayoutPanel extra){foreach(var number in new[]{offsetX,offsetY}){number.Minimum=-100;number.Maximum=100;number.DecimalPlaces=2;number.Increment=.1m;number.ValueChanged+=delegate{if(!updating)Schedule();};}Add(extra,new Label{Text=Loc.T("Korekcia X (mm)"),AutoSize=true});Add(extra,offsetX);Add(extra,new Label{Text=Loc.T("Korekcia Y (mm)"),AutoSize=true});Add(extra,offsetY);
  foreach(var number in new[]{scaleX,scaleY}){number.Minimum=80;number.Maximum=120;number.DecimalPlaces=2;number.Increment=.1m;number.Value=100;number.ValueChanged+=delegate{if(!updating)Schedule();};}scaleX.AccessibleName=Loc.T("Mierka X (%)");scaleY.AccessibleName=Loc.T("Mierka Y (%)");Add(extra,new Label{Text=scaleX.AccessibleName,AutoSize=true});Add(extra,scaleX);Add(extra,new Label{Text=scaleY.AccessibleName,AutoSize=true});Add(extra,scaleY);
  ignoreDriverMargins.Text=Loc.T("Ignorovať tlačiteľnú oblasť ovládača");ignoreDriverMargins.AutoSize=true;ignoreDriverMargins.MaximumSize=new System.Drawing.Size(270,0);ignoreDriverMargins.CheckedChanged+=delegate{if(!updating)Schedule();};Add(extra,ignoreDriverMargins);
  Add(extra,Button(Loc.T("Použiť rozmery dokumentu"),UseDocumentPaper));Add(extra,new Label{Text=Loc.T("Názov profilu média"),AutoSize=true});profileName.MaxLength=120;profileName.AccessibleName=Loc.T("Názov profilu média");Add(extra,profileName);
  Add(extra,Button(Loc.T("Uložiť profil tlačiarne"),SaveMediaProfile));
  Add(extra,Button(Loc.T("Odstrániť profil média"),delegate{var profile=mediaProfiles.SelectedItem as PrinterProfile;if(profile==null||profiles==null||busy||sending)return;if(UiMessageBox.Show(this,Loc.T("Odstrániť profil média?")+"\r\n"+profile.DisplayName,Loc.T("Profil média"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;try{profiles.Delete(profile.Printer,profile.DisplayName);updating=true;try{RefreshProfiles(profile.Printer,null);profileName.Clear();}finally{updating=false;}}catch(Exception ex){info.Text=ex.Message;}}));
  Add(extra,new Label{Text=Loc.T("Ak je výtlačok posunutý doprava alebo nadol, zadajte nameraný posun so záporným znamienkom. Mierku upravujte len podľa nameraného výtlačku. Automatické prispôsobenie vypnite vo vlastnostiach tlačiarne pred otvorením sprievodcu."),AutoSize=true,MaximumSize=new System.Drawing.Size(270,0)});
  calibrationLaunch=Button(Loc.T("Sprievodca kalibráciou…"),ShowCalibration);Add(extra,calibrationLaunch);
 }
 Action<Control> calibrationStyle;bool calibrationDark;
}
}
